CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE roles(id BIGSERIAL PRIMARY KEY,name VARCHAR(50) UNIQUE NOT NULL);INSERT INTO roles(name) VALUES('ROLE_TEACHER'),('ROLE_PARENT'),('ROLE_SCHOOL'),('ROLE_ADMIN') ON CONFLICT DO NOTHING;
CREATE TABLE users(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),email VARCHAR(255) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,first_name VARCHAR(100) NOT NULL,last_name VARCHAR(100) NOT NULL,phone VARCHAR(50),role VARCHAR(30) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,verified BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE teacher_profiles(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID UNIQUE NOT NULL,headline VARCHAR(255),bio TEXT,city VARCHAR(120),district VARCHAR(120),address VARCHAR(255),hourly_rate INT,salary_expectation INT,avatar_url VARCHAR(500),intro_video_url VARCHAR(500),verified BOOLEAN DEFAULT FALSE,experience_years INT,languages VARCHAR(500),availability_json TEXT,updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE school_profiles(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID UNIQUE NOT NULL,name VARCHAR(255),city VARCHAR(120),district VARCHAR(120),address VARCHAR(255),description TEXT,logo_url VARCHAR(500),website VARCHAR(500),phone VARCHAR(50),employee_count INT);
CREATE TABLE job_offers(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),school_id UUID,title VARCHAR(255),subject VARCHAR(150),level VARCHAR(100),city VARCHAR(120),contract_type VARCHAR(80),salary_min INT,salary_max INT,description TEXT,status VARCHAR(40) DEFAULT 'OPEN',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE applications(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),job_id UUID,teacher_id UUID,status VARCHAR(40) DEFAULT 'NEW',cover_letter TEXT,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE course_requests(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),parent_id UUID,teacher_id UUID,subject VARCHAR(150),level VARCHAR(100),mode VARCHAR(50),city VARCHAR(120),district VARCHAR(120),budget INT,schedule_json TEXT,status VARCHAR(40) DEFAULT 'PENDING',notes TEXT,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE bookings(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),parent_id UUID,teacher_id UUID,course_request_id UUID,starts_at TIMESTAMP,ends_at TIMESTAMP,amount INT,mode VARCHAR(50),status VARCHAR(50) DEFAULT 'PENDING_PAYMENT',payment_status VARCHAR(40) DEFAULT 'UNPAID',meeting_url VARCHAR(500),address VARCHAR(500),created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE reviews(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),booking_id UUID,author_id UUID,teacher_id UUID,rating INT NOT NULL,comment TEXT,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE conversations(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_a UUID,user_b UUID,updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE messages(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),conversation_id UUID,sender_id UUID,body TEXT,type VARCHAR(30) DEFAULT 'TEXT',read BOOLEAN DEFAULT FALSE,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE notifications(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID,type VARCHAR(80),title VARCHAR(255),body TEXT,link VARCHAR(500),read BOOLEAN DEFAULT FALSE,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE teacher_documents(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),teacher_id UUID,type VARCHAR(80),file_url VARCHAR(1000),status VARCHAR(40) DEFAULT 'PENDING',rejection_reason TEXT,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE payments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),booking_id UUID,payer_id UUID,amount INT,currency VARCHAR(10) DEFAULT 'XOF',provider VARCHAR(80),method VARCHAR(80),external_reference VARCHAR(255),status VARCHAR(40) DEFAULT 'PENDING',created_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX idx_teachers_city ON teacher_profiles(city);CREATE INDEX idx_jobs_status ON job_offers(status);CREATE INDEX idx_apps_job ON applications(job_id);CREATE INDEX idx_messages_conv ON messages(conversation_id);CREATE INDEX idx_notifications_user ON notifications(user_id);
